const c=$input.first().json;
if(!['demo','download'].includes(c.mode))throw Error('mode must be demo or download');
if(!/^[a-z0-9_-]{1,60}$/i.test(c.assetId))throw Error('Use a safe assetId');
for(const k of ['printWidthInches','printHeightInches'])if(!Number.isFinite(c[k])||c[k]<=0||c[k]>100)throw Error('Invalid print dimensions');
if(!Number.isFinite(c.minimumPpi)||c.minimumPpi<72||c.minimumPpi>600)throw Error('Invalid PPI');
if(!Array.isArray(c.variants)||!c.variants.length||c.variants.length>4)throw Error('Choose 1–4 variants');
const names=new Set();for(const v of c.variants){if(!/^[a-z0-9_-]{1,30}$/i.test(v.name)||names.has(v.name))throw Error('Unique safe variant names required');names.add(v.name);for(const k of ['width','height'])if(!Number.isInteger(v[k])||v[k]<16||v[k]>4096)throw Error('Invalid variant bounds');}
if(c.mode==='download'&&!/^https:\/\/images\.unsplash\.com\/[a-zA-Z0-9/_.,%?=&+-]+$/.test(c.sourceUrl))throw Error('Only trusted images.unsplash.com HTTPS image URLs are supported; redirects disabled');
return [{json:c}];
